class Solution {
  private int[] digits;
  private int target;
  private int[][][][] memo;

  private int dfs(int pos, int sum, int prod, boolean tight, boolean started) {
    if (sum > target) return 0;
    if (pos == digits.length) return started && sum == target && prod == 0 ? 1 : 0;
    int s = started ? 1 : 0;
    if (!tight && memo[pos][sum][prod][s] >= 0) return memo[pos][sum][prod][s];
    int limit = tight ? digits[pos] : 9, res = 0;
    for (int d = 0; d <= limit; d++) {
      boolean st = started || d != 0;
      int np = st ? (prod * d) % target : prod;
      res += dfs(pos + 1, sum + d, np, tight && d == limit, st);
    }
    if (!tight) memo[pos][sum][prod][s] = res;
    return res;
  }

  private int count(int x) {
    if (x <= 0) return 0;
    String str = String.valueOf(x);
    digits = new int[str.length()];
    for (int i = 0; i < digits.length; i++) digits[i] = str.charAt(i) - '0';
    int total = 0;
    for (target = 1; target <= 9 * digits.length; target++) {
      memo = new int[digits.length][target + 1][target][2];
      for (int[][][] a : memo) for (int[][] b : a) for (int[] c : b) java.util.Arrays.fill(c, -1);
      total += dfs(0, 0, 1 % target, true, false);
    }
    return total;
  }

  public int beautifulNumbers(int l, int r) {
    return count(r) - count(l - 1);
  }
}
